n = int(input())
a = list(map(int, input().split()))
cnt = {}
for i in range(n):
	mn = a[i]
	for j in range(i, n):
		mn = min(mn, a[j])
		if mn in cnt:
			cnt[mn] += 1
		else:
			cnt[mn] = 1
q = int(input())
for i in range(q):
	k = int(input())
	if k in cnt:
		print(cnt[k])
	else:
		print(0)
